INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1192105-ics202', 'stk-al-mulazim', 'ICS 202', 'info', '{"desc": "كورس كريه لكن مفيد ومهم جدا…\n\nواذا كنت CS وماعجبك هالكورس… غير التخصص immediately !\n\nall hardcore programmers should master the topics covered by this course", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/5", "user": "Al-Mulazim", "ts": 1361989972000, "tid": 120838, "pn": 5}}', 1361989972000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1192267-ics202', 'stk-the_giant', 'ICS 202', 'info', '{"desc": "أصنفه مايل للصعوبة لكن مو لهالدرجة , الطلاب تبالغ شوي بوصفه\nالكورس من اسمه Data Structure\nوالي هو بنية البيانات وكيف ترتبها وتربطها بالذاكرة , كل طريقة معينة لها فائدة , شيء يسرع البحث وشيء للترتيب\nزي إلي أخذتوه بآخر الـ 201 لو تذكر الـ ArrayList وهالأشياء لكن اللهم ما رح تتعلم كيف تستعملها\nرح تتعلم كيف تكتب كلاس كامل زي الـ ArrayList مثلا وكيف تصميمه من جوا\n\nوآخر نقطة بالكورس(بالواقع هي أول شي تدرسه) وهو أصعب شي بالكورس , شوية ماث وطرقة حسابية حتى تقدر تحسب فعالية الكود واستهلاكه للمعالج حتى تقدر تطبقه على الكلاسات إلي راح تكتبوها بعدين\n\nهذا باختصار الكورس كاملا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/6", "user": "The_Giant", "ts": 1362008697000, "tid": 120838, "pn": 6}}', 1362008697000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1197257-ics202', 'stk-baby_engineer', 'ICS 202', 'info', '{"desc": "الكورس مهم جدا في التخصص ، وثقيل شوي\n\nالكورس يتكلم عن الـ data structures ويشطح شوي على الـ complexity of a code لكن ما يتعمق فيه\n\nوآخر جزء منه (بنظري هو أمتع جزء) اللي هو الـ data compression لكن للأسف رآح تاخذه بشكل موجز جدا جدا وراح يعطيك الفكرة في ضغط الملفات بدون أي تعمق وبدون أي coding …\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/7", "user": "baby_engineer", "ts": 1362836481000, "tid": 120838, "pn": 7}}', 1362836481000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1373939-ics202', 'stk-computist', 'ICS 202', 'info', '{"desc": "جودة المقرر بشكل عام جيد جدا\nالمواضيع التي يغطيها المقرر\n\nComplexity Analysis\nyou ganna learn how much costly this code or that code in terms of time T & number of steps(operations) n ~ T(n) z\naUpper bound O(f(n)) and lower bound big-theta(f(n)z\na eg. linear search is O(n) while binary search is O(lg n)z\nyou will learn how to analyze **iterative **algorithms as well as recursive ones\n\nData Structures\ni. LinkedList(SLL,DLL,CSLL,CDLL, …)z\nii. Stack iii. Queue\niv. Trees ( BSTree, AVLTree, Heaps, BTree, B+Tree, …)z\nv. Graphs ( directed, undirected, weightedD, weightedU) z\n\nHashing\nhow to achieve O(1) access time\n\nCompression\nzip, rar, and other variants\nyou will learn the principles behind minimizing storage cost\nrun-length\nhuffman\nLZ78\n\nالكتاب المستخدم للمقررجيد بس أفضل ارجع للسلايدات\n\nالأسئلة والأمثلة المستخدمة في المقرركافية\n\nمدى فائدته في الناحية التطبيقيةمهم جدا انك تعرف كيفية تنظيم البيانات data-structures وهو كورس تحل فيه المشاكل الحياتية من خلال بعض الأفكار الأساسية، فعلى سبيل المثال نصمم تمثيل لطابور الإنتظار Queue ونستطيع نستخدمه بمختلف الأشكال في حل كثير من المشاكل، احس شيء ممتع انك تصنع حل لمشكلة بدل الاستعانة بحلول الآخرين، وهذا يعطيك قوة واستقلالية عن معونة الآخرين independence، احببت في الكورس الجزء الآخير compression ولو أضافو عليه encryption لكان افضل لأنه في العادة برامج الضغط مثل WinRAR أو WinZip أو غيرها تعطي خيار التشفير للمستخدم\n\nاحس هالكورس ممتع، وأسهل من الي قبله 201", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/10", "user": "Computist", "ts": 1401368686000, "tid": 120838, "pn": 10}}', 1401368686000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437801-ics202', 'stk-bo_rayan', 'ICS 202', 'info', '{"desc": "ع كلام الدكتور ال a+ من 90 وبعد كذا كل قريد خمس درجات\n\nقالنا هالكلام من بداية السمستر ف ما اتوقع الافرج بياثر\n\nالقريدات بكرا الصبح بتنزل في البورتال\n\nSent from my XT1063 using Tapatalk", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/16", "user": "Bo_Rayan", "ts": 1451760311000, "tid": 120838, "pn": 16}}', 1451760311000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1445905-ics202', 'stk-aaimsh', 'ICS 202', 'info', '{"desc": "من أهم المواد الذي يجب أن يتقنها المبرمج المادة سهلة ولكنها مهمة في نفس الوقت\n\nستتعرف على هياكل البيانات الأخرى:\nlinked list\nTrees وأنواعها الكثيرة\nstack\nqueue\nGraphs", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/17", "user": "aaimsh", "ts": 1459868685000, "tid": 120838, "pn": 17}}', 1459868685000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1512789-ics202', 'stk-dhafer_s_al-hajri', 'ICS 202', 'info', '{"desc": "انا حاليا قاعد اخذها مع الدكتور بشير غاندي في كلية الجبيل الجامعية (طبعا الدكتور بشير كان يدرس المادة في البترول زمان) الدكتور شديد جدا و المادة تسهل بعد الميدتيرم … يعني من Trees و طالع تعتبر ابسط من الدروس اللي قبل … عموما المادة ماهي سهله الصراحه يبيلها شغل و بحكم انها ما تبت بتخصص الMIS بصله ف حنا نبي فيها الستر بس … 🤪 :sweat:", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/18", "user": "Dhafer_S_Al-Hajri", "ts": 1563802532000, "tid": 120838, "pn": 18}}', 1563802532000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1516408-ics202', 'stk-ahmelq', 'ICS 202', 'info', '{"desc": "ICS202 - Data structures - 172\nمع الغني عن الوصف د. وصفي الخطيب.\n\nتطرق المادة إلى\n\nلجزء من التحليل العقدي (complex analysis) تساعدك تختار أفضل خوارزمية من ضمن عدة خوارزميات تسوي نفس المهمة.\n\nLinked Lists\n\nStacks and queues: راح تشوف تطبيقات عملية أكثر على هالمواضيع في كورسات مثل Networking و Intro. to AI\n\nRecursion & Analysis\n\nGraphs & Trees\n\nBalanced Trees, AVL Trees and Heaps\n\nB-Trees and B+-Trees : راح تشوفها تطبيقات لها في مقرر الـ Database\n\nHashing\n\nCompression\n\nالمادة فيها لاب مفتوح ومشروع، كان عبارة عن تطبيق لهذه الورقة.\nالكتاب كان سيء نوعاً ما، كنت أكتفي بشرح د. وصفي وسلايداته، وبعض الماتيرال على الإنترنت.\n\nلا تخاف أبداً من المادة، ذاكرها كل نهاية أسبوع، أحسن طريقة لفهمها أنك تشتري سبورة صغيرة وتحاول تشرح لنفسك، تطبق الخوارزميات خطوة بخطوة، السبورة أحسن من الورقة لأن تقدر تمسح بسهولة. إذا مافهمت حاجة من السلايدات ضروري تقعد وتشرح لنفسك، شاهد يوتيوب وابحث لين ماتفهم. لا تخليها تتراكم، أغلب اللي تدرسه بمر عليك في كورسات ثانية فلا تفوت شي، وحاول تسوي queue وstack مثلاً بنفسك.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/20", "user": "ahmelq", "ts": 1571886269000, "tid": 120838, "pn": 20}}', 1571886269000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518518-ics202', 'stk-user11151', 'ICS 202', 'info', '{"desc": "ICS202 - Data structures - 191\n\nالمادة سهلة جدا ولا هي قد الكلام اللي قريته فوق، الصعوبة في جزئية الميجر الأول أما ما بعده فهو سهل جدًّا جدًّا …\nسلايدات المادة معقدة واليوتيوب مليان شرح لكل المواضيع الخاصة بالمادة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/21", "user": "user11151", "ts": 1577809857000, "tid": 120838, "pn": 21}}', 1577809857000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533221-ics202', 'stk-posty', 'ICS 202', 'info', '{"desc": "ICS-202 Term211\nجودة المقرر بشكل عام: الكورس مواضيعه مرتبه و مرتبطه في بعض بالنسبه لشخص اخذ كان في اول دفعه تاخذ ics 104-108 اشوف الكورس جدا منظم مقارنة بالي قبلهم\n\nالمواضيع التي يغطيها المقرر: الكورس يبدا في مقدمة عن الكومبليكستي وكيف تحسب تعقيد وكفاءة بعض العبارات البرمجية لاكنه بشكل مبسط جدا، بعدين يبدا في الداتا ستركشرز و الالقرثمز بداية من اللينكد ليست و الستاكس و الكيو والتريز و القرافز الخ\n\nصعوبة المقرر: الكورس دسم للامانه ويحتاج تعطيه حقه وزي ماذكرت المواضيع مرتبطه في بعض اذا فيه درس مافهمته ممكن ياثر على الدروس القادمة\n\nاللاب: كان عبارة عن تطبيق للي تدرسه في الليكتشر من الداتا ستركشرز و الالقرثمز، اشوفه كان جميل وماكانت التاسكات صعبه اضافة ان كوردنيتر اللاب كان سامح يكون ديدلاين كل لاب اللاب الي بعده\n\nبروجكت اللاب: كان عبارة عن انك تسوي داتا ستركشر الي هي الtrie\n\nاضافات: مع هذا الكورس راح تبدا تحس انك طالب حاسب، الكورس مو برمجة كثر ما انه يشرح لك كيف تحل المشاكل وكيف تتعامل مع البيانات…\nبالنسبه لي مقارنة بكورسات ics الماضية هذا كان افضلهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-data-structures/120838/22", "user": "Posty", "ts": 1640988221000, "tid": 120838, "pn": 22}}', 1640988221000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p64136-ics202', 'stk-user524', 'ICS 202', 'info', '{"desc": "اخوي Dreams_Maker الله يعطيك العافية … طبعا غير السلايدات نبي اللي تقدر تجيبه من اسئلة مياجر وكوزات وهوموركات … يعني كل المياجر القديمة اللي عندك + كل مايعطونكم كوز أو هوموورك أو ميجر توضع بملف مضغوط وترسلي نسخة وأنا راح اكلم المشرف العام TheCollector يحطها في قسم ماتيريال الـICS وإن شاء الله راح يساعد …فيه مواقع فيه شروح وأمثل حلوة لكن المقصد من هذا كله نبغى نذاكر بالطريقة اللي عندنا وطرقة مدرسينا …\nولك الأجر والثواب بإذن الله في كل شخص يستفيد منها 🙂\nلك خالص شكري 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics232-swe-214-ics202/39778/13", "user": "user524", "ts": 1100909144000, "tid": 39778, "pn": 13}}', 1100909144000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p64139-ics202', 'stk-dreams_maker', 'ICS 202', 'info', '{"desc": "كاتب الرسالة الأصلية سفمور بوي\nاخوي Dreams_Maker الله يعطيك العافية … طبعا غير السلايدات نبي اللي تقدر تجيبه من اسئلة مياجر وكوزات وهوموركات … يعني كل المياجر القديمة اللي عندك + كل مايعطونكم كوز أو هوموورك أو ميجر توضع بملف مضغوط وترسلي نسخة وأنا راح اكلم المشرف العام TheCollector يحطها في قسم ماتيريال الـICS وإن شاء الله راح يساعد …فيه مواقع فيه شروح وأمثل حلوة لكن المقصد من هذا كله نبغى نذاكر بالطريقة اللي عندنا وطرقة مدرسينا …\nولك الأجر والثواب بإذن الله في كل شخص يستفيد منها 🙂\nلك خالص شكري 🙂\n\nفاهم عليك\n\nبس المشكلة الكويزات والمياجر والهوموورك على قولتك…راح تكون مجرد اسألة…لانه الأجوبة ماراح يعطونا اياها…لازم انت تروح للمدرس وياعالم إذا وقت الأوفيس حقه يناسب البريك حقك…وفي الأخير…زين إذا فهمت منه وش يقول…\n\nيعني الحالة صعبة جداً\n\nإذا بغيت الهوم ورك…وأسئلة اللاب…راح اعطيك اياها…\nأما المياجر والكويزات…فـ صعبة…لانها على ورق…\n\nمع إحترامي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics232-swe-214-ics202/39778/14", "user": "Dreams_Maker", "ts": 1100910866000, "tid": 39778, "pn": 14}}', 1100910866000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p514243-ics202', 'stk-user3083', 'ICS 202', 'info', '{"desc": "شوف انا بعطيك تجربتي خلال هذا الترم لان حاليا انا اخذ المادة عند محمد سعيد\n\nالدكتور هذا متفاني جدا جدا في مهنته وما يقصر ابد في التدريس\nيعدل السلايدات اول بأول ويحاول قد ما يقدر ينفع الطالب\nكويزاته سهلة سهلة جداااااا\n\nمشكلته انه جدي 24 ساعة وممل في الغالب\n\nبالنسبة لالفي هو معروف في القسم بشكل عام انه ممتاز جدا\nلكن بالنسبة لي اشوف مشكلته كويزاته صعبة والبروجكت (هذا اذا كانت المادة فيها بروجكت بس هذي المادة ما فيها) يكون صعععععععععععععب\n\nادري ان الشرح من جنبها لكن هذا اللي قدرت عليه واذا عندك اي سؤال لا تتردد عطني خبر 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-202-for-092/81604/2", "user": "user3083", "ts": 1262444731000, "tid": 81604, "pn": 2}}', 1262444731000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533313-ics202', 'stk-mohammed_mag', 'ICS 202', 'info', '{"desc": "المادة: ICS 202 - LAB - TERM 211\n\nالتحضير : ينادي بدايه الكلاس على الاسامي , ويتسامح مع التأخير\n\nطريقة الشرح : جدا واضحه ومتواجد اذا تبي أي سؤال عن التاسك .\n\nالكويزات : سهله\n\nالمياجر: ميد تيرم كومن\n\nالفاينلات : الفاينل كومن ايضا\n\nالقريد النهائي: A+\n\nالصوت: واضحه\n\nإضافات : الدكتور جدا مريح من ناحيه الحضور , المهم انك تسوي الي عليك وتطلع بدري .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-alturki/184179/2", "user": "Mohammed_Mag", "ts": 1641337627000, "tid": 184179, "pn": 2}}', 1641337627000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1534055-ics202', 'stk-wiss_alamri', 'ICS 202', 'info', '{"desc": "ICS202 “LAB” - term211 In Person\n\nالتحضير :\nيحضر كل لاب بعد 5 دقايق من بداية اللاب ومرات بعد 10 دقايق، ما يقول شيء عالتأخير بس قوله انك جيت ويحضرك.\n\nطريقة الشرح :\nيشرح التاسكات بشكل مبسط ومختصر بحيث انك تفهم وش المطلوب منك بالضبط.\n\nالكويزات :\nكان فيه 2 لاب كويز، الأول كان شوي صعب والثاني سهل.\n\nالمياجر: ----\n\nالفاينلات : -----\n\nالقريد النهائي:\nA++++++++++ وبجدارة وأحس اني ظلمته كمان.\n\nالصوت:\nواضح.\n\nإضافات :\n- الدكتور متساهل جدا الله يسعده بحيث انه اذا تبي تطلع بدري حتى لو ما خلصت التاسكات عادي عنده ويعطيك أسبوع كامل الين تسلم التاسكات.\n- تصحيح الدكتور أسطوري ويحرجك، لدرجة إنه حتى لو سلمت اللاب بعد نهاية الديدلاين وكان كودك صحيح بيعطيك الدرجة كاملة وما يشيل السبميشن من البلاكبورد، بالمناسبة حتى لو ما سلمت شيء بيعطيك نص الدرجة تخيل عزيزي القارئ، الدرجة من 10 واذا ما سلمت شيء يعطيك 5 ويكتب No Submission. 👏 🥰\n- في البروجيكت الوضع كان عنده سهالات وما كان يحشر كثير، بالنسبة لي خلاني اشرح كيف سويت الفنكشن وسويت الديمو وخلاص، كثير عطاهم درجة كاملة بالبروجيكت.\n- الدكتور لا زال صغير في العمر وفي سن الشباب ويساعدك لو احتجت شيء.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-alturki/184179/5", "user": "Wiss_Alamri", "ts": 1648971088000, "tid": 184179, "pn": 5}}', 1648971088000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p156592-ics202', 'stk-swe_student', 'ICS 202', 'info', '{"desc": "السلام عليكم\n\n* عليك بالمواد الثلاثة : ( ICS 102 + ICS 201 + ICS 202 ) كمحور لاختيار التخصص\nلأنهم لكل تخصصات الحاسب\nإذا رأيت انك انسان تأقلمت مع هذه المواد وهي مواد في البرمجة وأساسياتها واحترافها\nحبيت تلك المواد … وحسيت انك راح تبدع وراح تنتج وراح تطور نفسك بنفسك\n\nفأنا أنصحك بالـSWE\n\n-------\n\nبالنسبة للـAverage على حسب الماده\nبعض المواد اخذتها وكانوا عدد الطلاب يتجاوز الـ20 والافرج كان فيها معقول\n\nبعض المواد وكان عدد الطلاب فيها لايتجاوز الـ8 وكان الأفرج فيها عالٍ جداً ( ولكن في هذه الماده بالذات أتيحت لي فرصه الـA+ وأخذتها ولله الحمد لأني قدرت اثبت نفسي عند الدكتور مافي طلاب كثير)\n\n----------\n\nبالنسبة للطلاب الأجانب :\nماأزيد على ماذكره بعض الأخوة ان لافرق بينكم الا بالعقل والتفكير\n\n----------\n\nبالنسبة للشركات :\n\nفما أتوقع انك ماتعرف شركة ( الإلكترونيات المتقدمه )\nأكتفيت بهذا المثال فقط لأن الشركة كبيره وانتشارها على مستوى واسع\nومتخصصه في البرمجة وأمور الحاسب بشكل عام. (على حد علمي)\n\n----------\n\nنصيحتي لكل من أراد الدخول في هذا التخصص :\n\n* ان يكون محب للبرمجة\n* ان يتكيف مع أي لغة برمجة يتعلمها\n* ان يطور نفسه بنفسه ولا ينتظر احد لكي يعلمه\n* محاولة الإستفاده من المشاريع والواجبات ( وعدم أخذ المساعده الكلية من شخص آخر )\n* الإتكال على المولى عز وجل.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/swe/55319/12", "user": "SWE_Student", "ts": 1173876095000, "tid": 55319, "pn": 12}}', 1173876095000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p81911-ics202', 'stk-_911', 'ICS 202', 'info', '{"desc": "دخلت للتو في كورس الــ ICS202 ولازالت تواجهني حتى اليوم نفس المشكلة وهي:\n\nأني لا أجد أنه مشابه أبدا للكورسات السابقة (102 & 201)\n\nقرأت السلايدات ولكنها من غير فائدة\n\nإلى من يعرف كتابا ممتازا أو طريقة تجعلني أفهم الكورس بشكل أفضل وأكون له من الشاكرين.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/48729/1", "user": "_911", "ts": 1128331891000, "tid": 48729, "pn": 1}}', 1128331891000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p64258-ics202', 'stk-annoos', 'ICS 202', 'srcU', '{"html": "اتفضل 🙂<br><br>​<span data-fid=\"stk-f64258-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f64258-0": {"name": "lab06.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/lab06-ics202/42491/2", "user": "annoos", "ts": 1101033499000, "tid": 42491, "pn": 2}}', 1101033499000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p58699-ics202', 'stk-sshacker', 'ICS 202', 'srcU', '{"html": "هذه اللابات لICS 202<br>الى نهاية الترم<br><br>مع كم HW<br><br>ارجو ان تستعملها للفهم و ليس للحفظ هذي مادة لازم تكون فاهم فيها<br><br>وان كنت ساكن في الجامعة و عندك شبكة في الغرفة دور عمارة 2<br>جهاز anubis<br><br>بتلقاها ان شاء الله في مجلد مشارك و الكل مدعو في مجلد KFUPM<br><br>​<span data-fid=\"stk-f58699-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f58699-0": {"name": "ics202.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/5099f7ecb204887f854e7a176dd6ee45701a7d9ba932d3aaaba45f6c72a4894b"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics232-swe-214-ics202/39778/9", "user": "sshacker", "ts": 1095214881000, "tid": 39778, "pn": 9}}', 1095214881000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-shaheed_hussain-ics202', 'stk-shaheed_hussain', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98302", "n": "Dr. S Zhioua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ics202\nsem 121\n\nبنود التقييم :\n\nالتحضير :كل يوم يحضر,يحضر على ذاكرته يعني اذا شاف الطالب في اللكشر اليوم يعدي اسمه واذا لا يتأكد\nطريقة الشرح : على السلايدات واذا احتاج السبورة يتخدمها …بطل في الشرح ويفهمك كل نقطة بالتفصيل والبعض الاحيان بالتفصيل الممل\nالكويزات :سهلة\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:A\nالصوت:واضح\nإضافات :\nمشكلة هالدكتور لمن طالب يأله سؤال تشوفه يعفس وجه وهو يفكر واغلب الاحيان يفهم السؤال خطأ ويقعد يألف", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1165792-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-zhioua/98302/12", "user": "shaheed_hussain", "ts": 1358554090000, "tid": 98302, "pn": 12}}]}', 1358554090000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_red_blue-ics202', 'stk-the_red_blue', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS - 202\nT - 102\n\nأوّل أسبوع بشكل يومي، و بعدها بشكل شهري أو عن طريق البوب كويز.\n\nطريقة الشرح :\n\nهالإنسان بطل في الشرح، شرحه خرافي، النظري يشرحه من السلايدات، و إذا في مسألة أو مثال يحل المثال عالسبّورة، غالباً الحل ما يكون موجود في السلايدات، فعشان ما تنّكب، بس يحل مسألة عالسبورة اكتب الحل وراه. 🤠\n\nالكويزات :\nالمياجر:\nالفاينلات :\n\nغالباً يكون فيها تريكّات و تحتاج فهم.\n\nالقريد النهائي:\nA+\nالصوت:\n\nواضح\n\nإضافات :\nيكتبها لك بكل صراحة في السيلابص، الهوموركات، الكويزّات، الاختبارات، “Challenging”. 🤠\nفي عنده 5 درجات على -على الأقل- 10 بوب كويزز، طبعاً معظمكم بيخاف لمّا يشوف بوب كويز.\n\nالبوب كويز، لمّا يحل مسألة عالسبورة، يعطيكم مسألة مثلها باختلافات بسيطة، و يخلّي كل اثنين يحلّونها مع بعض في ورقة، و إذا تسأله أي سؤال يجاوبك و ما عنده أي مشكلة حتّى إنّه يحل لك جزء منه عشان تفهم.\n\nأنا شخصياً كنت أتمنّى يزيد البوب كويزز لأنّ درجاتها تكون في متناول اليد.\n\nالمدرّس أخلاقه جداً عالية، و متواضع، إذا تسأله عن شيء ما يعرفه يقول لك ما أعرفه، و أحياناً يبحث عن الجواب و يجي يقوله لك في اليوم الثاني.\n\nتصحيحه توب، يعطيك أكثر من حقّك في التصحيح.\nأستغرب إن شباب كثيرين ماخذين فكرة سيئة عن هالدكتور، أنا كنت مجبور أسجّل المادة معاه عشان الوقت، و كنت خايف من الكلام الي سمعته عنه، لكنّي شفت عكس هالكلام كليّاً !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p867072-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/8", "user": "The_Red_Blue", "ts": 1310444583000, "tid": 98306, "pn": 8}}]}', 1310444583000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmelq-ics202', 'stk-ahmelq', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور وصفي الخطيب - رجل غني عن التعريف -\nنزلت عنده ICS202 و ICS353.\nمحاضراته ممتعة، وتفاعلية، بعد الدرس يعطيك “أكتفيتي” والتحضير يكون بها.\nأتفهم ليش كثير من الطلاب ينتقدوه، عشان تفهم المادة صح الدكتور بطلعك من الـ\"comfort zone\" وبعطيك واجبات ومشاريع “طويلة/صعبة” نوعاً ما لكن فالنهاية بتفهم صح اذا اشتغلت.\n\nالتحضير\n: بداية ونهاية المحاضرة، وغالباً بالأكتفيتي شييتس. - الشرح\n: ممتاز جداً، الدرس من البداية للنهاية متناسق والأمثلة متدرجة في الصعوبة، وتفاعلي مع الطلاب. - الكويزات\n: سهلة إلى متوسطة إذا كنت تتابع معاه، وغالباً راح تكون شبيهة للمياجر القديمة. - المياجر والفينلات\n: سهلة لا تخلو من التحدي، راح يجيب أسئلة تتأكد أنك فاهم من المفاهيم ولا بس حفظ. وقبل الاختبارات يسوي هيلب سيشن\nالقريد النهائي: A+\nإضافات: الدكتور شامي دمث الخلق وعنده حس فكاهي، إذا كنت متحير بينه وبين دكتور ثاني فلا تفرط فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513007-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/22", "user": "ahmelq", "ts": 1564307003000, "tid": 98306, "pn": 22}}]}', 1564307003000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10578-ics202', 'stk-user10578', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ثلاث كورسات\nICS 202\nICS 254\nICS 353\n\nالتحضير : كل كلاس فيه اكتيفيتي يوزع اوراق وتحل تدريب عن الدرس وهذه منها التحضير واذا ما كان فيه يحضر تحضير عادي بالاسماء\n\nطريقة الشرح : يشرح من سلايداته الخاصة ويكتب عليها طول الشرح باستعمال الايباد حقه.\n\nالكويزات : متوسطة مائلة للصعوبة، الدكتور يطحن طحن في ذا الشي.\n\nالمياجر: متوسطة المستوى عادة الافرج بين 65 - 75\n\nالفاينلات : اشوفهم كانوا صعبين خصوصاً ICS 202 كان الافرج طايح\n\nالصوت: واضح\n\nإضافات : الدكتور يكرف بس تطلع بفائدة كل كلاس فيه اختبار عن الدرس او ما يسميه اكتيفيتي\nكويزاته و واجباته كثيرة ، كل كورساته فيها بروجكت بما فيها 254 و 353 بروجكت مصغر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1523212-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/24", "user": "user10578", "ts": 1592559435000, "tid": 98306, "pn": 24}}, {"id": "stk-dr-f118619", "n": "Dr. Emad Ramadan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 202 - 172\nICS 410 - 182\n- الشرح عادي من السلايدات ويخلص قبل النهاية واحياناً يطلب نحل مسألة ويحلها اخر شيء بالسبورة 🥊\n- ما كان يحضر لو تغيب الترم كامل ما يدري عنك بس لا تسحب وقت الكويزات 😂\n- ما يهتم بالتأخير 👏\n- المياجر والكويزات من سهلة الى متسوطة ويجيب اسئلة من الاولد اقزام 👏\n- الفاينلات حريقة وجهنمية طيحتني قريدين تقريباُ طول الترم نمدح فيه واخر شيء كذا 😡\n- الواجبات سهلة واذكر ما كان فيه قريدر واعطى كل واحد سلم درجة كاملة ههه (410) :trophy:\n- الصوت واضح انجليزي\\عربي\\مصري 👋\n- الخلاصة اذا تبي شرح شوف لك غيره اذا تبي درجات سجل عنده 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525255-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/emad-ramadan/118619/18", "user": "user10578", "ts": 1598808632000, "tid": 118619, "pn": 18}}]}', 1592559435000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-posty-ics202', 'stk-posty', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f118619", "n": "Dr. Emad Ramadan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 202-211\n\nالدكتور عماد رمضان\n\nالتحضير : مايحضر، لو ماتحضر طول الترم الا الكويزات عادي\nطريقة الشرح : للامانه شرحه جميل والدكتور فاهم ودمه خفيف وعسلللل بس بعض الاحيان يطول وهو ساكت ويطالع السلايدات تحسه ضايع بس ممكن بسبب كبر العمر يصير ينسى او شيء\nالكويزات : كانت كومن\nالمياجر: ميد\nالفاينلات :\nالقريد النهائي:\nالصوت:\nإضافات :الكورس جميل بس يحتاج تركيز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532692-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/emad-ramadan/118619/19", "user": "Posty", "ts": 1636486799000, "tid": 118619, "pn": 19}}, {"id": "stk-dr-f98307", "n": "Dr. Mohammad Said", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 202 Lab-211\n\nالتحضير : في نص اللاب\nطريقة الشرح : ماكان يشرح لان اللاب اصلا واضح ومايحتاج شرح\nالكويزات : اللاب كويزز كانت سهله\nالقريد النهائي:A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532693-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-said/98307/40", "user": "Posty", "ts": 1636486922000, "tid": 98307, "pn": 40}}]}', 1636486799000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-loop24-ics202', 'stk-loop24', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98307", "n": "Dr. Mohammad Said", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS202 - 212\n\nالتحضير :\nنهاية الكلاس ويحضرك حتى لو اخر دقيقة\n\nطريقة الشرح :\nيشرح السلايدات وشرحه أسطوري الصراحة يلم لك المادة مستحيل ماتفهم عليه\n\nالكويزات :\nما اذكر بس اذكر كانت متوسطة الى سهلة لو مركز معه بتجيب قريد فيها\n\nالميد:\nكان من الكورد او اثنينهم حطوه بس كان متوسط\n\nالفاينلات :\nنفس الميد\n\nالقريد النهائي:\nA\n\nإضافات :\nالدكتور مايبان عليه تعابير الوجه يكون ينكت وفجأة يفصل بس بشكل عام الدكتور أخلاق بس ينرفزه الي ينام بالكلاس او يقعد على الجوال يقول رح الكافتريا واذا خلصت أرجع،، ولعله كان داعس بالمنهج لدرجة اخر اسبوعين كلها ريفيو وعيى يعطينا اوف،، ثاني مرة درسني فيها الدكتور وشرحه ماعليه كلام مارح اتردد انزل عنده مرة ثانية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535876-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-said/98307/41", "user": "loop24", "ts": 1668072337000, "tid": 98307, "pn": 41}}]}', 1668072337000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-al-mulazim-ics202', 'stk-al-mulazim', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98313", "n": "Dr. Faisal Alvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 121\n\nICS 202 LAB\n\nكفو و متفهم لكن عند الدرجات انسى يعطيك شي مو لك…\nاللاب معاه سهالات صراحة… ما ادري عشان اني كويس في الجافا نفسها او هو من جد سهالات 🤠\n\nلاني كنت احضر عنده مثل الضيف واطلع بعض الاحيان وانا مدري ايش سويت بس في الاخير اخذت فل مارك معه ! (بجهدي !)\n\nوكنت افضل طالب عنده حسب كلامه 🤠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1154208-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-alvi/98313/19", "user": "Al-Mulazim", "ts": 1357244197000, "tid": 98313, "pn": 19}}]}', 1357244197000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cs_scientist-ics202', 'stk-cs_scientist', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98313", "n": "Dr. Faisal Alvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS202 Lab-152\n\nالتحضير : يحضر بعد ما يمر على اللاب ساعة\nبس اللي يحضرون متأخرين نص ساعة تقريبًا و فوق يحفظهم و يحطهم ليت\n\nطريقة الشرح :\nبالبداية يشرح الكونسبت حق اللاب بشكل سريع، ولو شاف إن فيه طلاب واجد مو فاهمين تعمّق و شرح أكثر، و عادي لو تسأله يجي يجلس معك و يشرح لك لين تفهم\n\nالكويزات :\nعطانا 2 لاب كويزز، تقريبًا متوسطين يميلون للسهولة\nكل الكويزين تكتب برنامج بالكمبيوتر و تسويله تيست و تتأكد زي ما تبغى، ما عنده شغلة إنك تكتب برنامج على ورقة\n\nالمياجر: ما فيه\n\nالفاينلات : ما فيه\n\nالصوت: واضح، يتكلم إنقليزي مع شوية لهجة هندية بس ينفهم كلامه بسهولة\n\nالقريد النهائي: A+ و بجدارة\n\nإضافات :\nفيه شيء أعجبني جدًا بالدكتور، إن اللاب تاسك ما عليه أي درجة، فـ إذا حضّر بعد ما يمر على اللاب ساعة تقدر تمشي\nو الدكتور حبيب و ما يقصر والله\nو في كويزات اللاب يوم شاف أغلب الطلاب محشورين مدد وقت الكويز\nو عطانا بروجيكت صراحة أشوفه سهل، و الأحلى إن الطلاب اللي عرضوا له البروجيكت و طلع فيه خطأ عطاهم فرصة ثانية إنهم يعدلون الخطأ و يسلمونه له مرة ثانية عشان ياخذون الدرجة كلها\nتحس يبيك تتعلم مو شغل يحجّر بالدرجات\n\nاللاب عليه 20%، 6% حضور و 7% كويزين لاب و 7% بروجيكت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1447914-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-alvi/98313/22", "user": "CS_Scientist", "ts": 1462185456000, "tid": 98313, "pn": 22}}, {"id": "stk-dr-f118619", "n": "Dr. Emad Ramadan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS202-152\n\nالتحضير :\nيحضر نهاية الكلاس، أحيانًا ما يحضر\nما يعطي ليت، يسمح بالميك أب\n\nطريقة الشرح :\nيشرح من سلايدات القسم، أشوف شرحه عادي و مش بطّال\n\nالكويزات :\nسهلة، من السلايدات\n\nالمياجر:\nالميجر الأول كان متوسط يميل للسهولة\nالميجر الثاني سهل\n\nالفاينلات :\nالفاينل كان سهل جدًا\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح، مع شوية لهجة مصرية بالشرح 😆\n\nإضافات :\nالدكتور ممتاز و سهّل علينا المادة الله يعافيه (كان ماسك المادة لحاله، ما معه دكتور ثاني)، و متعاون مع الطلاب\nنصيحة بعد كل اختبار راجعوه، لأن أحيانًا ما يفهم شيء و ينقص عليه، في ميجر 1 و الفاينل و في أحد الكويزات لقيته منقصني خطأ و راجعته و عدل لي الدرجة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450327-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/emad-ramadan/118619/14", "user": "CS_Scientist", "ts": 1464145527000, "tid": 118619, "pn": 14}}]}', 1462185456000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tryagain-ics202', 'stk-tryagain', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f118619", "n": "Dr. Emad Ramadan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 202 - Term 161\nالدكتور عماد رمضان\n\nالتحضير: أحيانا يحضر وأحيانا لا والتحضير يكون في نهاية الكلاس وما يهتم للتأخير أبداً\nطريقة الشرح: الشرح جيد جداً … الدكتور عماد ميزته يسهلك المادة بشكل كبير والمادة أساساً مو صعبة … في بداية الترم الدروس تكون صعبة شوي فـ الشرح لك عليه شوي … لكن بعدين لما ندخل في الـ strutures الشرح يكون ممتاز\nالكويزات: سهلة جداً وغالباً يعطيك السؤال اللي رح يجي فما يحتاج إلا تذاكر كم سلايد بس ويعطيك كويزات كثيرة ويحذف بعدين.\n\nالمياجر: هنا صار كم موقف خلاني أحب الدكتور عماد :blush-anim-cl:\nاولاً المادة كانت مشتركة بين الدكتور عماد والدكتور سامي زهيوا\n\nالميجر الاول : في بعض الاسئلة صححها الدكتور عماد والنص الثاني الدكتور سامي … كان في سؤال برمجة عليه 20 درجة وينحل بأقل من 5 سطور من نصيب الدكتور سامي … الاغلب ما كان حله بالبساطة هذي فنقص عليه الدكتور سامي تقريباً 7 وانا نقص علي 5 درجات … اعترضت للدكتور عماد وقلي خلاص إكتبلي الكود على الكمبيوتر ولو اشتغل ازيدلك … وفعلاً عطى اللي شغال كوده فل في السؤال … بالإضافة إلى إنه متساعد في التصحيح ولو راجعته يدفك شوي …\n\nالميجر الثاني: الدكتور عماد كان عنده سفر فأجل الميجر وخلا الميجر منفصل عن ميجر الدكتور سامي 😁2:\nجا قبل الميجر بيوم وقلنا على نوعية الأسئلة والـ algorithms اللي من الممكن انها تجي وفعلاً الاسئلة جات من الأشياء اللي قالها بالحرف لا زود ولا نقص فـ تقدر تقول الاختبار كان سهل وفي الجيب .\n\nالواجبات: عطانا واجبين بس بسبب إنو ما كان في قريدر بطل يعطينا اي واجب. الواجبين كانو سهلة الى متوسطة نوعاً ما.\n\nالدكتور بطل بطل بطل وأهم شي يعطيك الزبد 👍\n\nالنقييم النهائي : A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474766-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/emad-ramadan/118619/16", "user": "TryAgain", "ts": 1496931428000, "tid": 118619, "pn": 16}}, {"id": "stk-dr-f98313", "n": "Dr. Faisal Alvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 202 LAB - Term 161\n\nالتحضير : يحضر بعد مرور نصف ساعة تقريباً ويسجل المتأخرين\n\nالكويزات : كويزين متوسطة مائلة للسهولة والتصحيح فيها عسل أذكر إنو كان في الكويز الثاني سؤالين الأول حليتو صح والثاني كان ناقص ومع ذلك عطاني 3 من 3.\n\nالـ Assignments أو الـ Lab exercises ما عليها درجات فتسلمها أو ما تسلمها ما عندك أي مشكلة بس تراها مهمة لأنو أحياناً يجيب نفس الأفكار في الكويزات.\n\nالبروجكت: كان سهل جداً عبارة عن محرك بحثي بسيط … بس للأمانة مشكلة الدكتور إنو في بعض الأمور ما كان كاتبها في الـ project document وبعدين بعد ما بدينا في البروجكت وتعمقنا فيه قلنا نسيت أقلكم أحتاج كذا وكذا … فاضطرينا نعدل على البروجكت بشكل كبييير. ووقت التيست عنده نموذج في يده يشيك على الـ output ولو كان صح يعطيك فل لو كان غلط يعطيك مجال تزبط وتعدل. طبعاً البروجكت فيه بعض الطلبات الصعبة لكن تكون بونص لك مو اجباري إنك تسويها … واتوقع هذا البونص رح يجبر عنك غياباتك او حتى كويزاتك بس مالي متأكد من هذي النقطة\n\nعموماً الدكتور ممتاز وشرحه أكثر من رائع وما عنده أي مشكلة يجلس معاك ويفهمك مرة ومرتين وثلاثة … وتقدر تسألو على البروجكت ويساعدك فيه بشكل كبير\n\nأنصح فيه وبشدة وأكيد يستاهل A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474849-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-alvi/98313/28", "user": "TryAgain", "ts": 1497053361000, "tid": 98313, "pn": 28}}]}', 1496931428000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-breaktheunbreakable-ics202', 'stk-breaktheunbreakable', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98313", "n": "Dr. Faisal Alvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS202 - TERM 182\n\nالتحضير :\nكل كلاس بعد 10 دقائق. يسمح بالتأخير ولكن بيسجلك ليت غالبا. الدكتور ما يعطي DN\n\nطريقة الشرح :\nيشرح المكتوب في السلايدات كقراءة وتطبيق مثال أو مثالين. في بعض الدروس جيد، وأخرى تسليك.\nالكويزات:\nكويزاته سهلة ياخذ أفضل 4 من 5.\nالمياجر :\nاختبرنا ميجرين، الأول صعب والثاني سهل. أسئلة سامي بنظري سبرايز أكثر من ألفي D:\nالفاينل:\nالقريد النهائي: له B. طلعت معه ب A+\nالصوت:\nممتاز ولهجته مفهومة\nإضافات :\n1- أنا أحس دكتور ألفي مفروض يدرس مواد البرمجة، والألغوريثمز والداتا ستركشر لو تاخذها عند غيره مثل وصفي أو سامي يكون أحسن.\n2- المادة بها واجبات طويلة فاحسب حسابك\n3- ما عجبني تأخر درجات الواجبات وصعوبة مناقشتها، وهذا بسبب فصل الواجبات بين المدرسين والمصحح. نفس الشيء للمياجر.\n4- تصحيح ألفي سريييع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510174-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-alvi/98313/32", "user": "BreakTheUnbreakable", "ts": 1558772710000, "tid": 98313, "pn": 32}}]}', 1558772710000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-ics202', 'stk-mohammed_mag', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98313", "n": "Dr. Faisal Alvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: ICS 202 - LECTURE - TERM 211\n\nالتحضير : يحضر في نص المحاضرة بالضبط يوميا , والتأخير متعاون يعني اتوقع اذا جيت قبل نص المحاضره مايحطلك تأخير , بس بعدها يحطلك تأخير او يمكن غياب .\n\nطريقة الشرح : جدا واضحه وجميله , يمكن بتحس انه متسرع لأن الكورس فعلا جدا دسم وثقييييل , لكن هو الافضل في الشرح , ومتوفر ايضا له مقاطع لأترام ماضيه اون لاين , لكن للأسف هذه المقاطع فقط تغطي \" النصف الاول من الكورس \" , يعني النص الثاني الله يعين .\n\nالكويزات : نوعا ما كومن , يعني كل السكاشن تختبر بنفس اليوم محدد \" 4 اختبارات بالترم \" , وبالنسبه للصعوبه متوسطه .\n\nالمياجر: يوجد ميد كومن متوسط الصعوبه والوقت ضيق\n\nالفاينلات : الفاينل كومن ايضا , جدا الوقت ضيق , الماتريال حقه يتطلب حل اساله على الواحد يمكن من 10 دقايق الى 15 ساعه .\n\nالقريد النهائي: A+\n\nالصوت: جدا واضح\n\nإضافات : الدكتور جدا فاهم في المادة , وحبيب في الاوفس اور يساعدك بأقصى ماعنده , وأيضا مايحب اذا الطالب طلع جواله , يبغاك تركز بكل الطرق , وهو كوردنيتر اللاب فكان يتساعد ف بعض الظروف , انا نزلت عنده لكتشر وكان جدا مفيد ومساعد لي , لكن الي نزلو عندهم لاب مانصح فيه لان عطاهم بروجيكت جدا صعب .\nفأنصح تنزل عنده لكتشر بس ( لاتنزل عنده لاب )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533308-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-alvi/98313/36", "user": "Mohammed_Mag", "ts": 1641336635000, "tid": 98313, "pn": 36}}]}', 1641336635000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-o11-ics202', 'stk-o11', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f98313", "n": "Dr. Faisal Alvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيصل الڤي\n\nالمادة : ICS-202\nسمستر : 211\n\nالتحضير : يحضر في نص الكلاس وما كان يعطي تأخير. كان في الغالب يعطينا سوال نحله على بال ما يحضر.\n\nطريقة الشرح : يشرح من السلايدات وفي بعض الشباتر كان يخطر بعض السلايدات ويقول راح ارجع لها بعدين عشان يكون الشرح افضل.\n\nالكويزات : متوسطة للي مذاكر عدل\n\nالمياجر : كومن (قال لنا الدكتور ان كل سوال حطه دكتور في القسم و كل دكتور صحح السوال الي سواه)\n\nالقريد النهائي : A\n\nالصوت : واضح\n\nاضافات : الدكتور يسمح بالميك اب للكشر بس مب للكويزات. الدكتور طيب مره و اذا سالته يحاول يفهمك بطرق ثانية واذا سالته سوال ما يعرف جوابه بيبحث لك ويعطيك الجواب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533426-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-alvi/98313/37", "user": "O11", "ts": 1642000998000, "tid": 98313, "pn": 37}}]}', 1642000998000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-computist-ics202', 'stk-computist', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f118619", "n": "Dr. Emad Ramadan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS202\n\nالتحضير : آخر الحصة بس أحيانا ما يحظر\n\nطريقة الشرح : يستخدم السلايدات ويحل الأمثل مع الطلاب على السبورة ويحب الطلاب يطلعوا على السبورة ويشاركوا\n\nالكويزات : سهلة حوالي 6 كوزات\n\nالمياجر: common - متوسط الصعوبة\n\nالفاينلات : متوسط - سهل جدا\n\nالقريد النهائي: +B\n\nالصوت: واضح\n\nإضافات : أنصح فيه\n\nالمدرس متعاون مع الطلاب ويحب يخلص المنهج بالسرعة، أظن في هذا السمستر 132 عطانا حوالي 3 مرات OFF خلال السمستر وآخر كلاسين من السمستر OFF\nبس أحيانا احس من سرعته ما افهم على بعض المواضي فأضطر أراجع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373944-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/emad-ramadan/118619/13", "user": "Computist", "ts": 1401369317000, "tid": 118619, "pn": 13}}, {"id": "stk-dr-f102387", "n": "Dr. Ahmad Irfan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ics202 lab\n\nالتحضير : في بداية اللاب، العادة يتأخر حوالي 15 دقيقة\n\nطريقة الشرح : ممتازة يتناقش مع الطلاب في المفاهيم والأساسيات ومن ثم يوضح بعض الأفكار على السبورة\n\nالكويزات : سهلة بشكل غير متوقع\n\nالمياجر: -\n\nالفاينلات : -\n\nالقريد النهائي: A\n\nالصوت: واضح\n\nإضافات : من أفضل دكاترة الـ ics اللي درسوني، أنصح فيه بشدة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373946-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-irfan/102387/11", "user": "Computist", "ts": 1401369768000, "tid": 102387, "pn": 11}}]}', 1401369317000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omvr-ics202', 'stk-omvr', 'ICS 202', 'doc', '{"docs": [{"id": "stk-dr-f182632", "n": "Dr. Andri Mirzal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "192 (ايام كورونا) - ICS202\n\nالتحضير : اخر الكلاس ينادي بالاسم\nطريقة الشرح : حرفيا يقرا السلايدات\nالكويزات : نص ونص الى سهله\nالمياجر: كومن\nالفاينلات : 🤠NP\nالقريد النهائي:D\nالصوت: اكسنت سيء جدا جدا جدا جدا جدا\nإضافات: غيروا دكتورنا الى ميرزال بعد ٣ ايام من بداية السمستر كمفاجأة وكانت مفاجأة لعينة، الدكتور واضح انه مو فاهم المادة وقاعد يسلك بشكل، والمادة تحتاج دكتور فاهم ولا بتضيع( باستثناء اليوتيوب فيه ناس رهيبين وهم اللي نوعا ما انقذوني) اثناء الدراسة عن بعد كان يعطينا كويز كل محاضرة للتحضير، كويز سؤال واحد وغالبا يحتاج وقت وفهم كامل لمحتويات المحاضرة بمجموع ٣ كويزات بالاسبوع هذا غير الهومورك، الدكتور الثاني بالمادة كان يعطي سؤال تحضير واحد عبارة عن خيارات والسؤال يكون وش موضوع المحاضرة:)\nميزته انه يسمح بالجوال وبالميكب(للي يشوفونها ميزة)\nباختصار اهرب منه قد ماتقدر هذا اذا ما فاجأك الدبارتمنت وحطه لك غصب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521954-ics202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/andri-mirzal/182632/2", "user": "OMvR", "ts": 1589152921000, "tid": 182632, "pn": 2}}]}', 1589152921000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
